const matomoConfigured = !!(Cypress.env('MATOMO_URL') && Cypress.env('MATOMO_TOKEN') && Cypress.env('MATOMO_SITE_ID'));
if (matomoConfigured) {
  cy.task('log', '📊 Source : Matomo analytics');
  fetchTopPagesFromMatomo().then(pages => {
    if (pages && pages.length > 0) {
      cy.task('log', `✅ ${pages.length} pages récupérées depuis Matomo\n`);
      pages.forEach((p, i) => {
        cy.task('log', `  ${i + 1}. ${p.path} — ${p.visits} visites, ${p.pageviews} pages vues, temps moyen ${p.avgTime}s`);
      });
      // Stocker pour les tests suivants via un fichier fixture
      cy.writeFile('cypress/fixtures/matomo-top-pages.json', pages);
    } else {
      cy.task('log', '⚠️ Matomo n\'a retourné aucune donnée, fallback sur sitemap');
      fetchPagesFromSitemap().then(sitemapPages => {
        cy.writeFile('cypress/fixtures/matomo-top-pages.json', sitemapPages);
      });
    }
  });
} else {
  cy.task('log', '📍 Source : sitemap.xml (Matomo non configuré)');
  cy.task('log', '   Pour configurer Matomo, définir : MATOMO_URL, MATOMO_TOKEN, MATOMO_SITE_ID\n');
  fetchPagesFromSitemap().then(pages => {
    cy.task('log', `✅ ${pages.length} pages récupérées depuis le sitemap`);
    cy.writeFile('cypress/fixtures/matomo-top-pages.json', pages);
  });
}

cy.readFile('cypress/fixtures/matomo-top-pages.json').then(pages => {
  cy.task('log', `\n🔍 Test de disponibilité sur ${pages.length} pages\n`);
  const results = [];
  pages.forEach(({
    path,
    visits
  }) => {
    let fullUrl;
    try {
      fullUrl = new URL(path, BASE_URL).toString();
    } catch (_unused) {
      return;
    }
    cy.request({
      url: fullUrl,
      timeout: 15000,
      failOnStatusCode: false,
      followRedirect: true
    }).then(res => {
      const ok = res.status >= 200 && res.status < 400;
      results.push({
        path,
        status: res.status,
        ok,
        visits
      });
      const icon = ok ? '✅' : '❌';
      const visitInfo = visits > 0 ? ` (${visits} visites/semaine)` : '';
      cy.task('log', `${icon} [${res.status}] ${path}${visitInfo}`);
      expect(res.status, `${path} doit répondre correctement`).to.be.lessThan(400);
    });
  });
  cy.then(() => {
    const passed = results.filter(r => r.ok).length;
    const failed = results.filter(r => !r.ok).length;
    cy.task('log', `\n📊 Résultat: ${passed} OK, ${failed} KO`);
  });
});

cy.readFile('cypress/fixtures/matomo-top-pages.json').then(pages => {
  // Trier par visites (décroissant) et prendre le top 10
  const topPages = [...pages].sort((a, b) => (b.visits || 0) - (a.visits || 0)).slice(0, 10);
  cy.task('log', `\n⏱️ Performance des ${topPages.length} pages les plus visitées\n`);
  const timings = [];
  topPages.forEach(({
    path,
    visits
  }) => {
    let fullUrl;
    try {
      fullUrl = new URL(path, BASE_URL).toString();
    } catch (_unused2) {
      return;
    }
    const start = Date.now();
    cy.request({
      url: fullUrl,
      timeout: 15000,
      failOnStatusCode: false,
      followRedirect: true
    }).then(res => {
      const duration = Date.now() - start;
      timings.push({
        path,
        duration,
        visits
      });
      const icon = duration < 3000 ? '⚡' : '🐢';
      const visitInfo = visits > 0 ? ` (${visits} vis.)` : '';
      cy.task('log', `${icon} ${duration}ms — ${path}${visitInfo}`);
    });
  });
  cy.then(() => {
    if (timings.length === 0) return;
    const durations = timings.map(t => t.duration);
    const avg = Math.round(durations.reduce((a, b) => a + b, 0) / durations.length);
    const max = Math.max(...durations);
    const slowest = timings.find(t => t.duration === max);
    cy.task('log', `\n📊 Moyenne: ${avg}ms — Plus lente: ${max}ms (${slowest.path})`);
    // Les pages populaires doivent être rapides
    timings.forEach(({
      path,
      duration
    }) => {
      expect(duration, `${path} doit répondre en < 3s (actuel: ${duration}ms)`).to.be.lessThan(3000);
    });
  });
});

cy.readFile('cypress/fixtures/matomo-top-pages.json').then(pages => {
  const top3 = [...pages].sort((a, b) => (b.visits || 0) - (a.visits || 0)).slice(0, 3);
  cy.task('log', `\n🖥️ Vérification du rendu des 3 pages les plus visitées\n`);
  top3.forEach(({
    path,
    visits
  }) => {
    let fullUrl;
    try {
      fullUrl = new URL(path, BASE_URL).toString();
    } catch (_unused3) {
      return;
    }
    cy.visit(fullUrl, {
      timeout: 30000,
      failOnStatusCode: false
    });
    cy.document().its('readyState').should('eq', 'complete');
    cy.get('body', {
      timeout: 15000
    }).should('be.visible');
    // Vérifier qu'il y a du contenu visible
    cy.get('body').then($body => {
      const text = $body.text().trim();
      const visitInfo = visits > 0 ? ` (${visits} visites)` : '';
      expect(text.length, `${path} doit avoir du contenu`).to.be.greaterThan(50);
      // Vérifier qu'on n'est pas sur une page d'erreur
      const lower = text.toLowerCase();
      const isError = lower.includes('500 internal') || lower.includes('erreur serveur');
      cy.task('log', `${isError ? '❌' : '✅'} ${path}${visitInfo} — ${text.length} caractères`);
      expect(isError, `${path} ne doit pas être une page d'erreur`).to.be.false;
    });
  });
});
